scene.add(new THREE.HemisphereLight('#ffe9d0', '#6a5262', 1.55));
const moon = new THREE.DirectionalLight('#b7c8e8', .75);
moon.position.set(-4, 5, -4); scene.add(moon);
const lampGlow = new THREE.PointLight('#ffc990', 34, 8, 1.8);
lampGlow.position.set(-2.2, 2.45, -1.7); scene.add(lampGlow);
const fill = new THREE.PointLight('#d99a91', 12, 9); fill.position.set(3, 2.8, -1); scene.add(fill);
const room = new THREE.Group(); scene.add(room);
const interactables = [];
const mats = {};
const mat = (name, color, roughness=.8, extra={}) => mats[name] ||= new THREE.MeshStandardMaterial({ color, roughness, ...extra });
const cream = mat('cream','#eadbc9'), wallMat=mat('wall','#d9beba'), sideMat=mat('side','#bf9f9e'), wood=mat('wood','#875c4f'), paleWood=mat('paleWood','#b38670'), darkWood=mat('darkWood','#513d3c'), linen=mat('linen','#e7d5c7'), rose=mat('rose','#b6797e'), deepRose=mat('deepRose','#865b6b'), leaf=mat('leaf','#57755f'), leafLight=mat('leafLight','#819773'), brass=mat('brass','#c59762',.3,{metalness:.5}), glass=mat('glass','#8a9fac',.28,{metalness:.15}), ceramic=mat('ceramic','#e9d8c6',.3), night=mat('night','#415267',.9,{emissive:'#283345',emissiveIntensity:.3});
function mesh(geometry, material, parent=room, position=[0,0,0], cast=true, receive=true){const o=new THREE.Mesh(geometry,material);o.position.set(...position);o.castShadow=cast;o.receiveShadow=receive;parent.add(o);return o;}
function box(parent,pos,size,material,bevel=.04){const g=new THREE.BoxGeometry(...size);const o=mesh(g,material,parent,pos);if(bevel){const edge=new THREE.EdgesGeometry(g);const lines=new THREE.LineSegments(edge,new THREE.LineBasicMaterial({color:0xffffff,transparent:true,opacity:.08}));o.add(lines);}return o;}
function sphere(parent,pos,scale,material,segments=24){const o=mesh(new THREE.SphereGeometry(1,segments,Math.max(12,segments>>1)),material,parent,pos);o.scale.set(...scale);return o;}
function cylinder(parent,pos,rTop,rBot,height,material,segments=20){return mesh(new THREE.CylinderGeometry(rTop,rBot,height,segments),material,parent,pos);}
function roundedBox(parent,pos,size,radius,material){const shape=new THREE.Shape();const w=size[0],h=size[1],r=radius;shape.moveTo(-w/2+r,-h/2);shape.lineTo(w/2-r,-h/2);shape.quadraticCurveTo(w/2,-h/2,w/2,-h/2+r);shape.lineTo(w/2,h/2-r);shape.quadraticCurveTo(w/2,h/2,w/2-r,h/2);shape.lineTo(-w/2+r,h/2);shape.quadraticCurveTo(-w/2,h/2,-w/2,h/2-r);shape.lineTo(-w/2,-h/2+r);shape.quadraticCurveTo(-w/2,-h/2,-w/2+r,-h/2);const g=new THREE.ExtrudeGeometry(shape,{depth:size[2],bevelEnabled:true,bevelSegments:2,steps:1,bevelSize:.025,bevelThickness:.025});g.center();return mesh(g,material,parent,pos);}
// Architectural shell
box(room,[0,-.16,-1.1],[9,.3,8.4],mat('floor','#9d766b'),0);
box(room,[0,2.1,-5.24],[9,4.6,.24],wallMat,0);
box(room,[-4.48,2.1,-1.1],[.22,4.6,8.4],sideMat,0);
box(room,[4.48,2.1,-1.1],[.22,4.6,8.4],mat('rightWall','#cda9a3'),0);
box(room,[0,4.36,-1.1],[9,.2,8.4],mat('ceiling','#ead9ca'),0);
// Plank seams in floor, visible in the near foreground
for(let i=0;i<13;i++){const z=2.7-i*.62;box(room,[0,.002,z],[8.95,.012,.014],mat('seam','#765950'),0);for(let x=-3.6;x<4;x+=1.2)box(room,[x+((i%2)*.6),.004,z-.3],[.012,.014,.61],mat('seam','#765950'),0);}
// Rug
