rug.rotation.x=-Math.PI/2;
// pattern on rug as fine inset stitches
for(let x=-1.9;x<=1.9;x+=.24){const line=box(room,[x,.07,-.15],[.012,.012,2.23],mat('rugThread','#e4c4b4'),0);}
// Back wall window, deep midnight pane and mullions
