box(room,[-2.25,2.72,-4.89],[2.2,.045,.06],mat('windowGold','#bda98f'),0);
box(room,[-2.25,1.62,-4.8],[2.8,.12,.42],paleWood,0);
// Moon and stars behind window
sphere(room,[-2.9,3.15,-4.88],[.24,.24,.055],mat('moon','#f8dec0',.4,{emissive:'#f1cf9d',emissiveIntensity:.4}),28);
for(const [x,y,r] of [[-1.6,3.3,.035],[-2.1,3.5,.025],[-3.4,2.45,.025],[-1.4,2.55,.03],[-2.3,2.2,.022],[-3.1,3.55,.018]])sphere(room,[x,y,-4.86],[r,r,r],mat('star','#fff0d3',.35,{emissive:'#ffe4b6',emissiveIntensity:.7}),12);
// Curtain panels and rod
cylinder(room,[-2.25,3.91,-4.76],.035,.035,3.1,brass,16).rotation.z=Math.PI/2;
for(const x of [-3.55,-.95]){const c=box(room,[x,2.72,-4.7],[.38,2.38,.22],mat('curtain','#a8777d'),0);for(let j=0;j<4;j++)box(room,[x-.12+j*.08,2.7,-4.56],[.018,2.16,.025],mat('curtainFold','#c18b88'),0);}
// wall trim and framed botanical art
for(const x of [-4.25,4.25])box(room,[x,2.12,-4.96],[.08,4.3,.12],mat('trim','#f1e2d4'),0);
box(room,[2.52,2.98,-5.02],[1.22,1.48,.1],mat('frame','#7c5c53'),0);
box(room,[2.52,2.98,-4.95],[1.04,1.3,.055],mat('art','#e9d2bd'),0);
// stylized botanical painting strokes
for(let i=0;i<5;i++){const stem=cylinder(room,[2.52+(i-2)*.14,2.98,-4.91],.012,.018,.8,leaf,8);stem.rotation.z=(i-2)*.17; sphere(room,[2.52+(i-2)*.14,3.22+((i%2)*.12),-4.9],[.1,.19,.018],i%2?leafLight:leaf,12).rotation.z=(i-2)*.5;}

// Low, soft loveseat with tailored cushions
const sofa= new THREE.Group();room.add(sofa);sofa.position.set(1.38,0,-2.62);
box(sofa,[0,.36,0],[2.65,.72,.92],rose,0);
box(sofa,[0,.78,-.31],[2.74,.72,.3],deepRose,0);
for(const x of [-1.25,1.25]){const arm=roundedBox(sofa,[x,.61,.04],[.32,.68,.94],.14,rose);}
for(const x of [-.64,.04,.72]){const cushion=roundedBox(sofa,[x,.83,.05],[.62,.24,.68],.12,mat(`sofaCushion${x}`,x===.04?'#cf9b96':'#d99c99'));}
for(const x of [-.74,.78]){const pillow=roundedBox(sofa,[x,1.22,-.28],[.48,.46,.18],.13,linen);pillow.rotation.z=x<0?-.12:.12;}
for(const x of [-1,1])for(const z of [-.25,.25])cylinder(sofa,[x*1.04,.18,z],.05,.07,.36,darkWood,12);
// Side table and shaded lamp
const table= new THREE.Group();room.add(table);table.position.set(-2.2,0,-1.7);
cylinder(table,[0,.72,0],.46,.48,.12,paleWood,32);cylinder(table,[0,.37,0],.13,.19,.62,wood,20);cylinder(table,[0,.06,0],.38,.42,.1,wood,28);
const lampBase=cylinder(table,[-.04,.86,-.04],.17,.23,.14,brass,24);
cylinder(table,[-.04,1.12,-.04],.035,.035,.42,brass,16);
