// Book stack and teacup on the table
box(table,[.31,.84,.12],[.44,.075,.3],mat('book','#8d6871'),0).rotation.y=-.12;
box(table,[.3,.91,.12],[.39,.07,.27],mat('bookTop','#d8b89d'),0).rotation.y=.06;
const cup=cylinder(table,[.03,.96,.26],.13,.11,.21,ceramic,28);cup.userData={kind:'tea'};
const tea=cylinder(table,[.03,1.073,.26],.105,.105,.006,mat('tea','#99684b',.3),24);
const saucer=cylinder(table,[.03,.85,.26],.18,.18,.025,mat('saucer','#f6e8d5',.25),28);
const handle=mesh(new THREE.TorusGeometry(.09,.022,10,20,Math.PI*1.6),ceramic,table,[.17,.97,.26]);handle.rotation.z=Math.PI/2;
// Floor plant with layered leaves
const pot=cylinder(room,[-3.45,.42,-3.3],.38,.27,.76,mat('pot','#b98275',.55),32);
cylinder(room,[-3.45,.81,-3.3],.39,.39,.07,mat('soil','#514235'),32);
for(let i=0;i<9;i++){const a=i*2.4,r=.24+(i%3)*.07;const start=new THREE.Vector3(-3.45,.84,-3.3);const end=new THREE.Vector3(-3.45+Math.cos(a)*r,1.35+(i%4)*.12,-3.3+Math.sin(a)*r);const mid=start.clone().lerp(end,.5);const stem=mesh(new THREE.CylinderGeometry(.018,.025,start.distanceTo(end),9),leaf,room,mid.toArray());stem.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),end.clone().sub(start).normalize());const leafShape=sphere(room,end.toArray(),[.13,.31,.045],i%2?leaf:leafLight,16);leafShape.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),end.clone().sub(start).normalize());}
