for(let i=0;i<6;i++){const h=.38+(i%3)*.08;const b=box(room,[3.07+i*.15,.96+h/2,-3.42],[.105,h,.26],mat(`shelfBook${i}`,['#b97d79','#d5b68f','#788779','#8b7180','#dfc8a9','#a96f68'][i]),0);b.rotation.z=(i%2?.04:-.03);}
