for(let i=0;i<5;i++){const x=4.0+i*.07;const vine=mesh(new THREE.CylinderGeometry(.009,.013,.5+i*.05,8),leaf,room,[x,2.75,-3.4]);vine.rotation.z=-.22+i*.1;sphere(room,[x+.07,2.49-i*.06,-3.39],[.07,.15,.035],leafLight,12);}
// Companion, adult proportions, soft sculpted forms
const characterRoot=new THREE.Group();scene.add(characterRoot);characterRoot.position.set(.03,0,-2.16);
let companionParts=[];
function makeCompanion(type='mira'){
 while(characterRoot.children.length) characterRoot.remove(characterRoot.children[0]); companionParts=[];
 const isMira=type==='mira';const skin=mat(isMira?'skinM':'skinA',isMira?'#dca991':'#c9957d'), hair=mat(isMira?'hairM':'hairA',isMira?'#4c3738':'#433432'), shirt=mat(isMira?'shirtM':'shirtA',isMira?'#c58a87':'#82928c'), pants=mat(isMira?'pantsM':'pantsA',isMira?'#615968':'#505c63');
 const part=(o)=>{companionParts.push(o);return o;};
 // legs / shoes
 for(const x of [-.17,.17]){const leg=part(mesh(new THREE.CapsuleGeometry(.105,.57,5,12),pants,characterRoot,[x,.59,0]));leg.rotation.z=x>0?-.025:.025;sphere(characterRoot,[x,.16,.08],[.14,.085,.24],darkWood,18);}
 // natural torso and shoulders
 const torso=part(mesh(new THREE.CapsuleGeometry(.31,.67,8,18),shirt,characterRoot,[0,1.27,0]));torso.scale.set(1,.92,.72);
 for(const x of [-.33,.33]){const arm=part(mesh(new THREE.CapsuleGeometry(.105,.56,6,14),shirt,characterRoot,[x,1.31,.01]));arm.rotation.z=x<0?-.12:.12;const hand=sphere(characterRoot,[x*1.18,.94,.06],[.09,.12,.09],skin,18);part(hand);}
 // neck and gently shaped face
