53: joystick.addEventListener('pointermove',e=>{if(joyPointer!==e.pointerId)return;const dx=e.clientX-joyOrigin.x,dy=e.clientY-joyOrigin.y,len=Math.hypot(dx,dy),scale=Math.min(1,len/31);move={x:len?dx/len*scale:0,y:len?dy/len*scale:0};stick.style.transform=`translate(${move.x*24}px,${move.y*24}px)`;});
