content.text:
* {
box-sizing:border-box}
 :root {
font-family:'DM Sans',sans-serif;color:#443a3a;font-synthesis:none}
html,body,#game {
margin:0;width:100%;height:100%;overflow:hidden;background:#e8d8d1}
body {
touch-action:none}
button,input,select {
font:inherit}
button {
color:inherit}
#scene {
position:absolute;inset:0;width:100%;height:100%;display:block}
.vignette {
position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(34,28,30,.24),transparent 25%,transparent 68%,rgba(38,28,29,.28)),linear-gradient(90deg,rgba(42,27,31,.1),transparent 35%,transparent 75%,rgba(42,27,31,.08))}
.topbar {
position:absolute;z-index:2;top:max(22px,env(safe-area-inset-top));left:30px;right:30px;display:flex;align-items:center;justify-content:space-between;color:#fff;text-shadow:0 1px 10px #423b4070}
.brand {
display:flex;align-items:center;gap:12px}
.brand-mark {
display:grid;place-items:center;width:39px;height:39px;border-radius:14px;background:#fff2;color:#fff;font-size:21px;border:1px solid #ffffff50;backdrop-filter:blur(12px)}
.brand b {
font:700 14px Manrope,sans-serif;letter-spacing:.01em;display:block}
.brand small {
font-size:11px;opacity:.78;display:block;margin-top:3px}
.top-actions {
display:flex;gap:9px}
.icon-btn {
height:42px;width:42px;border-radius:14px;border:1px solid #ffffff55;background:#fff2;color:white;font-size:19px;backdrop-filter:blur(12px);cursor:pointer}
.scene-label {
position:absolute;left:34px;top:104px;color:#fff;letter-spacing:.16em;font-size:9px;font-weight:700;text-shadow:0 1px 8px #362c2c}
.live-dot,.mood-dot {
display:inline-block;width:6px;height:6px;border-radius:50%;background:#c9e8c1;margin-right:8px;box-shadow:0 0 9px #aee3a0}
.label-sep {
margin:0 11px;opacity:.65}
.companion-chip {
position:absolute;right:34px;top:96px;display:flex;align-items:center;gap:10px;padding:8px 11px 8px 8px;border:1px solid #ffffff60;background:#fffdf1c9;border-radius:16px;box-shadow:0 8px 28px #46363224;backdrop-filter:blur(16px);min-width:166px}
.avatar,.dialog-avatar {
display:grid;place-items:center;border-radius:12px;color:#fff;background:linear-gradient(145deg,#c88385,#72506f);font:700 17px Manrope}
.avatar {
height:38px;width:38px}
.companion-chip strong {
font:700 13px Manrope;display:block}
.companion-chip small {
display:block;color:#8a7774;font-size:10px;margin-top:4px}
.mood-dot {
background:#a9c399;width:5px;height:5px;margin-right:5px}
.swap {
margin-left:auto;border:0;background:transparent;color:#9c7774;font-size:19px;cursor:pointer}
.focus-hint {
position:absolute;top:46%;left:50%;transform:translate(-50%,-50%);border:1px solid #ffffff50;color:#fff;padding:10px 15px;border-radius:999px;background:#3d313136;backdrop-filter:blur(9px);font-size:11px;opacity:.88;white-space:nowrap;cursor:pointer}
.focus-hint b {
font-weight:500;opacity:.8}
.focus-hint i {
font-style:normal;padding-left:9px}
.look-note {
position:absolute;bottom:158px;left:50%;transform:translateX(-50%);color:#fff;font-size:10px;letter-spacing:.035em;text-shadow:0 1px 6px #382e2e;opacity:.77}
.conversation {
position:absolute;z-index:3;left:50%;bottom:132px;width:min(590px,calc(100% - 38px));transform:translate(-50%,18px);opacity:0;pointer-events:none;transition:opacity .28s,transform .28s}
.conversation.open {
opacity:1;transform:translate(-50%,0);pointer-events:auto}
.dialog-card {
padding:17px 19px 12px;border:1px solid #fff9;border-radius:18px;background:rgba(255,251,245,.94);box-shadow:0 14px 40px #49363830;backdrop-filter:blur(18px)}
.dialog-top {
display:flex;align-items:center;gap:11px}
.dialog-avatar {
height:40px;width:40px;border-radius:13px;font-size:17px}
.dialog-meta {
flex:1}
.dialog-meta strong {
font:700 13px Manrope;color:#614854}
.dialog-meta span {
font-size:11px;color:#b4868c;margin-left:5px}
.dialog-caption {
font-size:10px;color:#a59891;margin-top:4px}
.close-dialog,.close-settings {
border:0;background:none;color:#9c8b87;font-size:23px;cursor:pointer}
.dialog-card p {
font-size:14px;line-height:1.55;color:#514547;margin:14px 3px 8px}
.dialog-bottom {
display:flex;justify-content:space-between;align-items:center;color:#ab9a94;font-size:10px}
.speak-reply {
